<script setup lang="ts">import { ref } from 'vue'; import { useRouter } from 'vue-router'; import axios from 'axios'; import api from '../plugins/axios'; const router=useRouter(); const idCliente=ref(''); const celularCliente=ref(''); const idPresentacion=ref(''); const precio=ref(''); const descripcionPersonalizada=ref(''); const modalidad=ref<'domicilio'|'retiro'>('retiro'); const direccionEntrega=ref(''); const fechaEntrega=ref(''); const horaEntrega=ref('10:00'); const error=ref(''); async function crear(){try{const {data}=await api.post('/pedidos/personalizado',{idCliente:idCliente.value?Number(idCliente.value):undefined,celularCliente:celularCliente.value||undefined,idPresentacion:Number(idPresentacion.value),precio:precio.value,descripcionPersonalizada:descripcionPersonalizada.value,modalidad:modalidad.value,direccionEntrega:modalidad.value==='domicilio'?direccionEntrega.value:undefined,fechaEntrega:fechaEntrega.value,horaEntrega:horaEntrega.value,detalles:[]}); await router.push({name:'verificacion-pago',params:{id:data.pedido?.idPedido||data.idPedido}})}catch(e){error.value=axios.isAxiosError(e)?e.response?.data?.message??'No se pudo crear el pedido.':'No se pudo crear el pedido.'}}</script>
<template><section class="container py-5"><h1 class="h2 fw-bold mb-4">Pedido personalizado</h1><div class="row justify-content-center"><div class="col-12 col-lg-8"><div class="card border-0 shadow-sm"><div class="card-body"><div v-if="error" class="alert alert-danger">{{ error }}</div><div class="row g-3"><div class="col-md-6"><label class="form-label">ID del cliente</label><input v-model="idCliente" class="form-control" type="number" /></div><div class="col-md-6"><label class="form-label">o celular del cliente</label><input v-model="celularCliente" class="form-control" /></div><div class="col-md-6"><label class="form-label">ID de presentación</label><input v-model="idPresentacion" class="form-control" type="number" /></div><div class="col-md-6"><label class="form-label">Precio acordado</label><input v-model="precio" class="form-control" type="number" min="0" step="0.01" /></div><div class="col-12"><label class="form-label">Descripción personalizada</label><textarea v-model="descripcionPersonalizada" class="form-control"></textarea></div><div class="col-md-4"><label class="form-label">Modalidad</label><select v-model="modalidad" class="form-select"><option value="retiro">Retiro</option><option value="domicilio">Domicilio</option></select></div><div v-if="modalidad==='domicilio'" class="col-md-8"><label class="form-label">Dirección</label><input v-model="direccionEntrega" class="form-control" /></div><div class="col-md-6"><label class="form-label">Fecha de entrega</label><input v-model="fechaEntrega" class="form-control" type="date" /></div><div class="col-md-6"><label class="form-label">Hora de entrega</label><input v-model="horaEntrega" class="form-control" type="time" min="07:00" max="20:00" /></div></div><button class="btn btn-primary mt-4" type="button" @click="crear">Crear pedido personalizado</button></div></div></div></div></section></template>
